mapper.select:
SELECT
USER_ID AS userId
FROM users
WHERE USER_ID = #{userId}
AND USER_PWD = #{pwd}

mapper.update:
UPDATE users
SET USER_PWD = #{newPwd}
WHERE USER_ID = #{userId}

UPDATE pet
SET
PET_NAME = #{petName},
SPECIES = #{species},
BREED = #{breed},
BIRTHDATE = #{birthdate},
GENDER = #{gender}
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM pet
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.update:
UPDATE pet
SET IS_MAIN = 'N'
WHERE USER_ID = #{userId}

UPDATE pet
SET IS_MAIN = 'Y'
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.insert:
INSERT INTO PET_WEIGHT (
    PET_NO,
    WEIGHT,
    CDATE
) VALUES (
    #{petNo},
    #{weight},
    #{date}
)

mapper.update:
UPDATE PET_WEIGHT
SET
    WEIGHT = #{weight},
    CDATE = #{date}
WHERE WEIGHT_NO = #{id}

UPDATE PET_HEALTH
SET
    TITLE = #{title},
    MEMO = #{memo}
WHERE HEALTH_NO = #{id}

UPDATE subscription
SET IS_AUTO = #{isAuto}
WHERE USER_ID = #{userId}
AND SUB_NO = #{subNo}
AND DATE_SUB(N_DATE, INTERVAL 1 DAY) >= NOW()

mapper.select:
SELECT * FROM ( SELECT UP.POINT_NO AS pointNo, UP.USER_ID AS userId, UP.POINT_AMOUNT AS pointAmount, UP.ORD_NO AS ordNo, UP.REVIEW_NO AS reviewNo, DATE_FORMAT(UP.CDATE, '%Y-%m-%d %H:%i') AS cdate,
CASE WHEN UP.POINT_AMOUNT > 0 AND UP.REVIEW_NO IS NOT NULL THEN '리뷰 작성 적립' WHEN UP.POINT_AMOUNT > 0 THEN '포인트 적립' WHEN OI.firstProductName IS NULL THEN '포인트 사용' WHEN OI.productCnt > 1 THEN CONCAT(OI.firstProductName, ' 외 ', OI.productCnt - 1, '건') ELSE OI.firstProductName END AS orderProductText,
SUM(UP.POINT_AMOUNT) OVER ( PARTITION BY UP.USER_ID ORDER BY UP.CDATE ASC, UP.POINT_NO ASC ) AS balance
FROM USER_POINT UP
LEFT JOIN ( SELECT OD.ORD_NO, MIN(P.PRODUCT_NAME) AS firstProductName, COUNT(*) AS productCnt FROM ORDER_DETAIL OD JOIN PRODUCT P ON OD.PRODUCT_NO = P.PRODUCT_NO GROUP BY OD.ORD_NO ) OI ON UP.ORD_NO = OI.ORD_NO
WHERE UP.USER_ID = #{userId}
AND DATE(UP.CDATE) >= #{startDate}
AND DATE(UP.CDATE) <= #{endDate}
) X ORDER BY X.cdate DESC, X.pointNo DESC
